var i=`0127-medovik`;var n=`world-0127`;var a=`RU`;var o=`eastern-europe`;var s=10;var r=92;var g={en:`Medovik`,ua:`Медовик`};var l={en:`A classic dish from Russia, featuring chicken egg, sour cream, heavy cream, walnut. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Росія. Основні складники: куряче яйце, сметана, вершки високої жирності, волоський горіх. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Beat the listed ingredients until pale and light; ensure butter and eggs are at room temperature when specified.`,ua:`Збийте зазначені складники до світлої пишної маси; за потреби використовуйте масло та яйця кімнатної температури.`,t:[`creaming-butter-sugar`,`whisking`],m:12,i:[[`chicken-egg`,3,`pcs`],[`white-granulated-sugar`,200,`g`],[`unsalted-butter`,125,`g`],[`honey`,140,`g`]]},{en:`Warm the honey mixture gently until the baking soda foams. Off the heat, stir in flour to make a smooth dough that can be divided into thin layers.`,ua:`Обережно прогрійте медову суміш до реакції соди. Зніміть із вогню та вмішайте борошно, щоб отримати гладке тісто для тонких коржів.`,t:[`mixing`],m:8,i:[[`baking-soda`,6,`g`],[`all-purpose-flour`,480,`g`]]},{en:`Roll the dough into thin rounds, each baked separately at 180°C until golden; cool thoroughly before filling.`,ua:`Розкачайте тісто на тонкі круглі коржі та випікайте кожен окремо при 180°C до рум’яності; повністю остудіть перед прошаруванням.`,t:[`pressing`,`rolling-out-dough`],m:18,i:[]},{en:`Bake in a preheated 180°C oven for about 24 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 24 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:24,i:[]},{en:`Whisk or whip the listed ingredients to a smooth, light consistency, then keep cool until needed.`,ua:`Збийте зазначені складники до гладкої легкої консистенції, після чого зберігайте в прохолоді до використання.`,t:[`whipping`],m:8,i:[[`sour-cream`,650,`g`],[`heavy-cream`,180,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:22,i:[[`walnut`,100,`g`]]}];var u={slug:i,id:n,country:`RU`,region:o,servings:10,minutes:92,title:g,text:l,steps:h};export{a as country,u as default,n as id,r as minutes,o as region,s as servings,i as slug,h as steps,l as text,g as title};